SELECT SUM(QT_MAT_BAS) AS total_matrículas
FROM matriculas
WHERE (QT_MAT_BAS_0_3 > 0 OR QT_MAT_BAS_0_3 = 0) AND (QT_MAT_BAS_4_5 > 0 OR QT_MAT_BAS_4_5 = 0);

SELECT (SUM(QT_MAT_BAS_0_3) + SUM(QT_MAT_BAS_4_5)) AS total_matrículas
FROM matriculas
WHERE (QT_MAT_BAS_0_3 > 0 OR QT_MAT_BAS_0_3 = 0) AND (QT_MAT_BAS_4_5 > 0 OR QT_MAT_BAS_4_5 = 0);
